def answers():
    g = {'coding': [85, 70, None, 92, 64], 'art': [90, 60, 75, 58, 81], 'none': [82, None, 66, 71, 55]}
    def rates(drop_na, keep_none):
        r = []
        for k, v in g.items():
            if k == "none" and not keep_none:
                continue
            ok = [x for x in v if x is not None] if drop_na else v
            hi = sum(1 for x in ok if x is not None and x >= 80)
            r.append(hi / len(ok))
        return r
    out = []
    for d, k in [(True, True), (True, False), (False, True)]:
        r = rates(d, k)
        out += [max(r), min(r), round(max(r) - min(r), 3)]
    return out

